bad=[];clocks=[];checked=0
for n,v in left.items():
 if n in changed or str(b.findNet(n).getSigType())in ['POWER','GROUND']:continue
 checked+=1
 if str(b.findNet(n).getSigType())=='CLOCK':clocks.append(n)
 if right[n]!=v:bad.append(n)
r=dict(accepted=False,checked_unchanged_nets=checked,checked_clock_nets=len(clocks),changed_unselected_nets=bad,changed_clock_nets=sorted(set(bad)&set(clocks)),explicitly_released_clock_nets=sorted(clock_allowlist),actual_released_clock_changes=sorted(n for n in clock_allowlist if left[n]!=right[n]))
(out/'result.json').write_text(json.dumps(r,indent=2)+'\n')
